// n8n Code node: "Build Claude request"
const f = $input.first().json;

const meta = {
  client: (f['Client name'] || '').trim(),
  process: (f['Process name'] || '').trim(),
  interviewee: (f['Person interviewed'] || '').trim(),
  role: (f['Their role'] || '').trim(),
  interviewDate: f['Interview date'] || '',
};
const transcript = (f['Transcript'] || '').trim();

if (transcript.length < 200) {
  return [{ json: { Error: 'The transcript is too short to map (under 200 characters). Paste the full walkthrough transcript and submit again.' } }];
}

const system = `You are the Process Mapper for an AI implementation consultancy. You turn a recorded walkthrough of how someone does a task at work into an accurate, step-by-step process map.

Your map will be sent back to the person interviewed so they can confirm it, and later used to decide what to automate. Accuracy matters more than completeness: a wrong step is worse than a missing one.

Rules:
- Record only what the transcript says or clearly shows. Do not invent steps, tools, people or numbers.
- Each step is one action by one person in one tool. Split compound actions ("I copy it into the sheet and email Sarah") into separate steps.
- person: the role or name of whoever does the step. tool: the software or medium used (e.g. "Gmail", "QuickBooks", "paper form", "phone call"). If the transcript doesn't say, write "unknown" and add an open question.
- judgment_needed is true when the person has to decide something that isn't a fixed rule (e.g. "I check if it looks right", "depends on the customer"). Explain the decision in judgment_notes; otherwise leave judgment_notes empty.
- evidence: a short quote (under 25 words) from the transcript that supports the step.
- frequency_per_week and minutes_per_run: use numbers only if stated or directly calculable from what was said (e.g. "about 20 a day" on a 5-day week = 100). Otherwise use null and add an open question. Use minutes_per_run for one full run of the process, not one step.
- exceptions: what happens when things go wrong or differ from normal ("if the invoice is missing a PO number...").
- pain_points: frustrations, delays or errors the person mentions, in their words where possible.
- open_questions: specific questions to ask the person to fill gaps or resolve contradictions. Write them so they can be sent directly to that person.
- Write in plain English. No consulting jargon.`;

const str = { type: 'string' };
const nullableNumber = { anyOf: [{ type: 'number' }, { type: 'null' }] };
const schema = {
  type: 'object',
  additionalProperties: false,
  required: ['process_name', 'summary', 'owner', 'trigger', 'frequency_per_week', 'minutes_per_run', 'tools_used', 'steps', 'exceptions', 'pain_points', 'open_questions'],
  properties: {
    process_name: str,
    summary: str,
    owner: str,
    trigger: str,
    frequency_per_week: nullableNumber,
    minutes_per_run: nullableNumber,
    tools_used: { type: 'array', items: str },
    steps: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['n', 'action', 'person', 'tool', 'input', 'output', 'judgment_needed', 'judgment_notes', 'evidence'],
        properties: {
          n: { type: 'integer' },
          action: str, person: str, tool: str, input: str, output: str,
          judgment_needed: { type: 'boolean' },
          judgment_notes: str,
          evidence: str,
        },
      },
    },
    exceptions: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['when', 'what_happens'],
        properties: { when: str, what_happens: str },
      },
    },
    pain_points: { type: 'array', items: str },
    open_questions: { type: 'array', items: str },
  },
};

const userMessage = `<context>
Client: ${meta.client}
Process: ${meta.process}
Person interviewed: ${meta.interviewee}${meta.role ? ` (${meta.role})` : ''}
</context>

<transcript>
${transcript}
</transcript>

Build the process map for "${meta.process}" from this walkthrough.`;

const request = {
  model: 'claude-sonnet-5-5',
  max_tokens: 16000,
  fallbacks: 'default',
  output_config: { effort: 'medium', format: { type: 'json_schema', schema } },
  system,
  messages: [{ role: 'user', content: userMessage }],
};

return [{ json: { request, meta } }];

// n8n Code node: "Parse and check"
const res = $input.first().json;
const meta = $('Build Claude request').first().json.meta;

const PRICE_PER_MTOK = { input: 2.0, output: 10.0 }; // Claude Sonnet 5.5, USD

const fail = (msg) => [{ json: { Error: msg } }];

if (res.stop_reason === 'refusal') {
  return fail('Claude declined to process this transcript. Check it for content unrelated to the business process and try again.');
}
if (res.stop_reason === 'max_tokens') {
  return fail('The map was cut off because it was too long. Split the transcript into separate processes and submit each one.');
}
const textBlock = (res.content || []).find((b) => b.type === 'text');
if (!textBlock) {
  return fail(`Claude returned no map (stop reason: ${res.stop_reason || 'unknown'}).`);
}
let map;
try {
  map = JSON.parse(textBlock.text);
} catch (e) {
  return fail('Claude returned a map that could not be read. Submit the form again.');
}

const isUnknown = (v) => !v || /^\s*(unknown|n\/a|none|unclear)\s*$/i.test(v);
const steps = map.steps || [];
const issues = [];

const missingPerson = steps.filter((s) => isUnknown(s.person)).map((s) => s.n);
const missingTool = steps.filter((s) => isUnknown(s.tool)).map((s) => s.n);
if (steps.length === 0) issues.push('No steps were found in the transcript.');
const stepList = (ns) => (ns.length === 1 ? `Step ${ns[0]} has` : `Steps ${ns.join(', ')} have`);
if (missingPerson.length) issues.push(`${stepList(missingPerson)} no person.`);
if (missingTool.length) issues.push(`${stepList(missingTool)} no tool.`);
if (map.frequency_per_week == null) issues.push('How often this runs per week is unknown.');
if (map.minutes_per_run == null) issues.push('Minutes per run is unknown.');
if (!(map.exceptions || []).length) issues.push('No exceptions were described. Ask what happens when something goes wrong.');

const hoursPerWeek =
  map.frequency_per_week != null && map.minutes_per_run != null
    ? Math.round(((map.frequency_per_week * map.minutes_per_run) / 60) * 10) / 10
    : null;

const usage = res.usage || {};
const cost =
  ((usage.input_tokens || 0) * PRICE_PER_MTOK.input + (usage.output_tokens || 0) * PRICE_PER_MTOK.output) / 1e6;

const lines = [];
lines.push(`# ${map.process_name}`);
lines.push('');
lines.push(map.summary);
lines.push('');
lines.push(`Owner: ${map.owner}`);
lines.push(`Starts when: ${map.trigger}`);
lines.push(`Runs per week: ${map.frequency_per_week ?? 'unknown'} · Minutes per run: ${map.minutes_per_run ?? 'unknown'} · Hours per week: ${hoursPerWeek ?? 'unknown'}`);
lines.push(`Tools: ${(map.tools_used || []).join(', ')}`);
lines.push('');
lines.push('## Steps');
for (const s of steps) {
  lines.push(`${s.n}. ${s.action} (${s.person}, ${s.tool})`);
  lines.push(`   In: ${s.input} → Out: ${s.output}`);
  if (s.judgment_needed) lines.push(`   Judgment: ${s.judgment_notes}`);
}
if ((map.exceptions || []).length) {
  lines.push('');
  lines.push('## When things go differently');
  for (const x of map.exceptions) lines.push(`- If ${x.when}: ${x.what_happens}`);
}
if ((map.pain_points || []).length) {
  lines.push('');
  lines.push('## Pain points');
  for (const p of map.pain_points) lines.push(`- ${p}`);
}
if ((map.open_questions || []).length) {
  lines.push('');
  lines.push('## Questions for you');
  for (const q of map.open_questions) lines.push(`- ${q}`);
}

return [{
  json: {
    'Client': meta.client,
    'Process': map.process_name || meta.process,
    'Interviewee': meta.interviewee,
    'Interview date': meta.interviewDate || null,
    'Owner': map.owner,
    'Runs per week': map.frequency_per_week,
    'Minutes per run': map.minutes_per_run,
    'Hours per week': hoursPerWeek,
    'Step count': steps.length,
    'Judgment steps': steps.filter((s) => s.judgment_needed).length,
    'Exception count': (map.exceptions || []).length,
    'Checklist passed': issues.length === 0,
    'Checklist issues': issues.join('\n'),
    'Open questions': (map.open_questions || []).map((q) => `- ${q}`).join('\n'),
    'Map': lines.join('\n'),
    'Map JSON': JSON.stringify(map, null, 2),
    'Status': 'Awaiting confirmation',
    'Model': res.model || 'claude-sonnet-5-5',
    'AI cost (USD)': Math.round(cost * 10000) / 10000,
  },
}];
